                comps.append(comp)
    comp=max(comps,key=len)
    rs=[a for a,b in comp]; cs=[b for a,b in comp]
    r0,c0=min(rs),min(cs); s=max(max(rs)-r0,max(cs)-c0)+1
    motif={(a-r0,b-c0) for a,b in comp}
    # anchors
    anchors=[]
    for r in range(n-s+1):
        for c in range(m-s+1):
            ok=True
            for dr in range(s):
                for dc in range(s):
                    v=g[r+dr][c+dc]
                    if (dr,dc) in motif and v!=2: ok=False;break
                    if (dr,dc) not in motif and v not in (0,3): ok=False;break
                if not ok: break
            if ok and any(g[r+dr][c+dc]==2 for dr in range(s) for dc in range(s)):
                anchors.append((r,c))
    sp=s+1
    S={(r//sp,c//sp) for r,c in anchors}
    band={(r,c) for r in range(n) for c in range(m) if g[r][c]==3}
    for (i,j) in sorted(set(motif)-S):
        cells=[(i*sp+dr,j*sp+dc) for dr in range(s) for dc in range(s)]
        if all(p in band for p in cells):
            for dr,dc in motif: out[i*sp+dr][j*sp+dc]=2
            anchors.append((i*sp,j*sp))
    for r,c in anchors:
        i,j=r//sp,c//sp
        if (i,j) in motif: out[r+i][c+j]=8
    for r in range(n):
        for c in range(m):
            if g[r][c]==3: out[r][c]=0
    return out

